// @generated by the slice schematic from its spec. Edit in place; reshape via the spec and --force.
import { z } from 'zod';
import type { FormFieldMeta } from '../forms/form-field-meta';

export const heroSchema = z.object({
  name: z
    .string()
    .min(1, 'Codename is required')
    .meta({
      label: 'Codename',
      control: 'text',
      help: 'Public-facing hero name.',
    } satisfies FormFieldMeta),
  alias: z
    .string()
    .min(1, 'Alter ego is required')
    .meta({
      label: 'Alter ego',
      control: 'text',
      help: 'Civilian identity, kept off the public roster.',
    } satisfies FormFieldMeta),
  heroClass: z.enum(['Aerial', 'Energy', 'Psionic', 'Tech', 'Mutant', 'Cosmic', 'Enhanced']).meta({
    label: 'Power class',
    control: 'select',
    options: [
      { value: 'Aerial', label: 'Aerial' },
      { value: 'Energy', label: 'Energy' },
      { value: 'Psionic', label: 'Psionic' },
      { value: 'Tech', label: 'Tech' },
      { value: 'Mutant', label: 'Mutant' },
      { value: 'Cosmic', label: 'Cosmic' },
      { value: 'Enhanced', label: 'Enhanced' },
    ],
  } satisfies FormFieldMeta),
  power: z
    .number()
    .min(0, 'Power index must be at least 0')
    .max(100, 'Power index must not exceed 100')
    .meta({
      label: 'Power index',
      control: 'number',
      help: 'Power index, 0 to 100.',
    } satisfies FormFieldMeta),
  notes: z.string().meta({
    label: 'Field notes',
    control: 'textarea',
    help: 'Operational summary for the dossier.',
  } satisfies FormFieldMeta),
  active: z.boolean().meta({
    label: 'Active duty',
    control: 'checkbox',
    help: 'Available for mission assignment right now.',
  } satisfies FormFieldMeta),
});

export type HeroFormModel = z.infer<typeof heroSchema>;
