1	import { Injectable, computed, inject, signal } from '@angular/core';
2	import { toSignal } from '@angular/core/rxjs-interop';
3	import { ActivatedRoute, Router } from '@angular/router';
4	import type { BadgeVariants } from '@spartan-ng/helm/badge';
5	import { map } from 'rxjs';
6	import type { HeroFormModel } from '../hero/hero.schema';
7	import { HeroService } from '../hero/hero.service';
8	
9	type BadgeVariant = NonNullable<BadgeVariants['variant']>;
10	
11	export type HeroDetailTab = 'overview' | 'powers' | 'missions' | 'edit';
12	
13	const TABS: readonly HeroDetailTab[] = ['overview', 'powers', 'missions', 'edit'];
14	
15	/** Every piece of copy the detail screen shows. The template binds to these and never repeats them. */
16	const HERO_DETAIL_TEXT = {
17	  back: 'Back to roster',
18	  rosterRoute: '/roster',
19	  notFound: 'No hero matches this record. It may have been retired.',
20	  deploy: 'Deploy',
21	  retire: 'Retire',
22	  retireTitle: 'Retire this hero?',
23	  retireDescription:
24	    'The hero will be removed from the roster. This cannot be undone.',
25	  retireConfirm: 'Retire hero',
26	  cancel: 'Cancel',
27	  sections: 'Hero sections',
28	  tabs: {
29	    overview: 'Overview',
30	    powers: 'Powers',
31	    missions: 'Missions',
32	    edit: 'Edit',
33	  },
34	  overview: {
35	    summary: 'Field summary',
36	    dossier: 'Dossier',
37	    noNotes: 'No field notes on file.',
38	    missions: 'Missions',
39	    missionsHint: 'Logged to date',
40	    successRate: 'Success rate',
41	    successHint: 'Across logged missions',
42	    power: 'Power index',
43	    powerHint: 'Out of 100',
44	  },
45	  powers: {
46	    meter: 'Power index',
47	    classification: 'Classification',
48	  },
49	  missions: {
50	    summary: 'Mission record',
51	    successful: 'Successful',
52	    unsuccessful: 'Unsuccessful',
53	    note: 'Per-deployment logs are not in the example data. These totals are derived from the hero record.',
54	  },
55	  edit: {
56	    submit: 'Save changes',
57	  },
58	  dossier: {
59	    codename: 'Codename',
60	    alias: 'Alter ego',
61	    heroClass: 'Power class',
62	    power: 'Power index',
63	    status: 'Status',
64	    clearance: 'Clearance tier',
65	    duty: 'Active duty',
66	    onDuty: 'On duty',
67	    offDuty: 'Off duty',
68	  },
69	} as const;
70	
71	const STATUS_VARIANTS: Readonly<Record<string, BadgeVariant>> = {
72	  Active: 'success',
73	  Injured: 'warning',
74	  Reserve: 'outline',
75	  MIA: 'destructive',
76	};
77	
78	export interface DossierRow {
79	  readonly label: string;
80	  readonly value: string;
81	}
82	
83	export interface MissionRow {
84	  readonly label: string;
85	  readonly value: string;
86	  readonly variant?: BadgeVariant;
87	}
88	
89	/**
90	 * State for one hero's detail screen. Component-scoped: the screen provides it, so each
91	 * visit gets a fresh view model that follows the route's `:id` rather than a stale snapshot.
92	 */
93	@Injectable()
94	export class HeroDetailViewModel {
95	  private readonly heroService = inject(HeroService);
96	  private readonly router = inject(Router);
97	  private readonly route = inject(ActivatedRoute);
98	
99	  readonly text = HERO_DETAIL_TEXT;
100	
101	  // The router reuses this component when only the id changes, so the id is read as a
102	  // stream rather than from a snapshot taken once in ngOnInit.
103	  private readonly id = toSignal(
104	    this.route.paramMap.pipe(map((params) => params.get('id') ?? '')),
105	    { initialValue: '' },
106	  );
107	
108	  readonly hero = computed(() => this.heroService.byId(this.id()));
109	
110	  readonly activeTab = signal<HeroDetailTab>('overview');
111	
112	  readonly initials = computed(() => this.hero()?.name.slice(0, 2).toUpperCase() ?? '');
113	
114	  readonly statusVariant = computed<BadgeVariant>(() => {
115	    const hero = this.hero();
116	    return hero ? (STATUS_VARIANTS[hero.status] ?? 'outline') : 'outline';
117	  });
118	
119	  /** Deploy puts a hero on active duty. An injured or missing hero cannot be sent out. */
120	  readonly canDeploy = computed(() => {
121	    const hero = this.hero();
122	    return !!hero && !hero.active && hero.status !== 'Injured' && hero.status !== 'MIA';
123	  });
124	
125	  readonly dossier = computed<readonly DossierRow[]>(() => {
126	    const hero = this.hero();
127	    if (!hero) return [];
128	    const rows = this.text.dossier;
129	    return [
130	      { label: rows.codename, value: hero.name },
131	      { label: rows.alias, value: hero.alias },
132	      { label: rows.heroClass, value: hero.heroClass },
133	      { label: rows.power, value: String(hero.power) },
134	      { label: rows.status, value: hero.status },
135	      { label: rows.clearance, value: hero.clearance },
136	      { label: rows.duty, value: hero.active ? rows.onDuty : rows.offDuty },
137	    ];
138	  });
139	
140	  /** The result totals are derived from the record's missions and success rate, not a deployment log. */
141	  readonly missionRows = computed<readonly MissionRow[]>(() => {
142	    const hero = this.hero();
143	    if (!hero) return [];
144	    const won = Math.round((hero.missions * hero.successRate) / 100);
145	    return [
146	      { label: this.text.overview.missions, value: String(hero.missions) },
147	      { label: this.text.missions.successful, value: String(won), variant: 'success' },
148	      { label: this.text.missions.unsuccessful, value: String(hero.missions - won), variant: 'destructive' },
149	      { label: this.text.overview.successRate, value: `${hero.successRate}%` },
150	    ];
151	  });
152	
153	  selectTab(key: string): void {
154	    const tab = TABS.find((candidate) => candidate === key);
155	    if (tab) this.activeTab.set(tab);
156	  }
157	
158	  deploy(): void {
159	    if (!this.canDeploy()) return;
160	    this.heroService.update(this.id(), { active: true });
161	  }
162	
163	  retire(): void {
164	    this.heroService.remove(this.id());
165	    void this.router.navigateByUrl(this.text.rosterRoute);
166	  }
167	
168	  save(model: HeroFormModel): void {
169	    this.heroService.update(this.id(), model);
170	    this.activeTab.set('overview');
171	  }
172	
173	  cancel(): void {
174	    this.activeTab.set('overview');
175	  }
176	}
177

